<script setup>
import { Link } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import Pagination from '../../Components/Pagination.vue';
import ReleaseResult from '../../Components/ReleaseResult.vue';
import ReservationState from '../../Components/ReservationState.vue';
import { reservationDate } from '../../reservations';
defineProps({ evaluacion: Object, alcance: String, validaciones: Object, eventos: Object });
</script>
<template><AppLayout title="Detalle de evaluación" section="Liberación"><div class="page-heading"><div><span class="section-context">EVALUACIÓN {{ evaluacion.id }}</span><h1>{{ evaluacion.espacio.nombre }}</h1><p>{{ evaluacion.espacio.codigo }} · {{ reservationDate(evaluacion.fecha_hora) }}</p></div><Link :href="`/liberacion/evaluaciones?alcance=${alcance}`" class="btn btn-secondary">Volver a evaluaciones</Link></div><section class="panel form-panel"><ReleaseResult :value="evaluacion.resultado"/><h2>{{ evaluacion.politica.nombre }} · v{{ evaluacion.politica.version }}</h2><p>{{ evaluacion.motivo }}</p><p v-if="evaluacion.resultado === 'ALERTAR'" class="alert" role="status">Requiere atención / condición de posible no utilización. La reserva se conserva.</p><p>Reserva: {{ evaluacion.reserva.codigo }}</p><p>Estado actual: <ReservationState :value="evaluacion.reserva.estado"/></p><p class="hint">Este registro conserva la decisión tomada con la evidencia disponible en su fecha. La disponibilidad también depende del estado operativo, bloqueos y mantenimiento.</p></section>
    <template v-if="alcance === 'administrativas'"><section class="panel table-panel"><div class="form-panel"><h2>Evidencia QR considerada</h2><p>Validaciones vinculadas a esta evaluación.</p></div><div class="table-scroll" tabindex="0" role="region" aria-label="Evidencia QR considerada, tabla desplazable"><table><thead><tr><th>Fecha</th><th>Resultado</th><th>Validado por</th></tr></thead><tbody><tr v-for="(q, i) in validaciones.data" :key="i"><td>{{ reservationDate(q.fecha_hora) }}</td><td>{{ q.resultado === 'VALIDA' ? 'Válida' : 'Inválida' }}</td><td>{{ q.actor }}</td></tr><tr v-if="!validaciones.data.length"><td colspan="3" class="empty-cell">No se enlazaron validaciones QR en esta evaluación.</td></tr></tbody></table></div><Pagination :data="validaciones"/></section><section class="panel table-panel"><div class="form-panel"><h2>Evidencia IoT considerada</h2><p>Lecturas de los sensores relevantes en la ventana de evaluación.</p></div><div class="table-scroll" tabindex="0" role="region" aria-label="Evidencia IoT considerada, tabla desplazable"><table><thead><tr><th>Sensor</th><th>Tipo</th><th>Valor</th><th>Fecha del evento</th><th>Recepción</th></tr></thead><tbody><tr v-for="(e, i) in eventos.data" :key="i"><td>{{ e.sensor }}</td><td>{{ e.tipo === 'PRESENCIA' ? 'Presencia' : 'Ocupación' }}</td><td>{{ e.valor ?? 'Sin valor' }}</td><td>{{ reservationDate(e.fecha_evento) }}</td><td>{{ reservationDate(e.fecha_recepcion) }}</td></tr><tr v-if="!eventos.data.length"><td colspan="5" class="empty-cell">No se enlazaron eventos IoT en esta evaluación.</td></tr></tbody></table></div><Pagination :data="eventos"/></section></template>
  </AppLayout></template>
